/** SHA-1 hex digest without Node.js `crypto` (safe in workflow bundles). */
function sha1Hex(data) {
	const words = new Uint32Array(80);
	const bitLength = data.length * 8;
	const padded = new Uint8Array(data.length + 9 + 63 >> 6 << 6);
	padded.set(data);
	padded[data.length] = 128;
	const view = new DataView(padded.buffer);
	view.setUint32(padded.length - 4, bitLength >>> 0, false);
	view.setUint32(padded.length - 8, Math.floor(bitLength / 4294967296), false);
	let h0 = 1732584193;
	let h1 = 4023233417;
	let h2 = 2562383102;
	let h3 = 271733878;
	let h4 = 3285377520;
	for (let offset = 0; offset < padded.length; offset += 64) {
		for (let j = 0; j < 16; j++) words[j] = view.getUint32(offset + j * 4, false);
		for (let j = 16; j < 80; j++) words[j] = rotl(words[j - 3] ^ words[j - 8] ^ words[j - 14] ^ words[j - 16], 1);
		let a = h0;
		let b = h1;
		let c = h2;
		let d = h3;
		let e = h4;
		for (let j = 0; j < 80; j++) {
			let f;
			let k;
			if (j < 20) {
				f = b & c | ~b & d;
				k = 1518500249;
			} else if (j < 40) {
				f = b ^ c ^ d;
				k = 1859775393;
			} else if (j < 60) {
				f = b & c | b & d | c & d;
				k = 2400959708;
			} else {
				f = b ^ c ^ d;
				k = 3395469782;
			}
			const temp = rotl(a, 5) + f + e + k + words[j] >>> 0;
			e = d;
			d = c;
			c = rotl(b, 30);
			b = a;
			a = temp;
		}
		h0 = h0 + a >>> 0;
		h1 = h1 + b >>> 0;
		h2 = h2 + c >>> 0;
		h3 = h3 + d >>> 0;
		h4 = h4 + e >>> 0;
	}
	return [
		h0,
		h1,
		h2,
		h3,
		h4
	].map((word) => word.toString(16).padStart(8, "0")).join("");
}
function rotl(value, bits) {
	return (value << bits | value >>> 32 - bits) >>> 0;
}
